div.script:

            document.addEventListener('DOMContentLoaded', function () {
            const menuItems = document.querySelectorAll('.cont-account-menu .menu-item');
            const sections = document.querySelectorAll('.dinamic-info .content-section');

            // Manejo de clics en el menú
            menuItems.forEach(item => {
                item.addEventListener('click', function (e) {
                // Verificar si es un enlace externo (con target="_blank")
                    const link = this.querySelector('a');
                    if (link && link.hasAttribute('target') && link.getAttribute('target') === '_blank') {
                        // No hacer nada, dejar que el enlace funcione normalmente
                        return;
                    }
                    e.preventDefault();
                    menuItems.forEach(i => i.classList.remove('active'));
                    sections.forEach(s => s.classList.remove('active'));
                    this.classList.add('active');
                    const targetId = this.getAttribute('data-target');
                    const targetSection = document.getElementById(targetId);
                    if (targetSection) {
                        targetSection.classList.add('active');
                    }
                });
            });

            // Lógica del formulario
            const profileForm = document.getElementById('profile-form');
            const editButton = document.getElementById('enable-edit');
            const actionButtons = document.getElementById('action-buttons');
            const discardButton = profileForm.querySelector('.profile-discard');
            const profileMessage = document.getElementById('profile-message');
            const inputs = profileForm.querySelectorAll('input:not([type="hidden"]), select, textarea');
            const profileNameEls = document.querySelectorAll('.profile_name');
            const profileEmailEls = document.querySelectorAll('.profile_email');

            function setProfileHeader({ name = null, email = null }) {
                if (name !== null) {
                    profileNameEls.forEach(el => el.textContent = name);
                }
                if (email !== null) {
                    profileEmailEls.forEach(el => el.textContent = email);
                }
            }

            // Inicializar formulario en modo solo lectura
            inputs.forEach(input => {
                input.setAttribute('disabled', 'disabled');
            });
            editButton.style.display = 'block';
            actionButtons.style.display = 'none';

            // Botón Edit
            if (editButton) {
                editButton.addEventListener('click', function (e) {
                    e.preventDefault();
                    inputs.forEach(input => {
                        input.removeAttribute('disabled');
                    });
                    editButton.style.display = 'none';
                    actionButtons.style.display = 'block';
                    profileMessage.innerHTML = '';
                });
            }

            // Botón Discard
            if (discardButton) {
                discardButton.addEventListener('click', function () {
                    inputs.forEach(input => {
                        input.setAttribute('disabled', 'disabled');
                    });
                    editButton.style.display = 'block';
                    actionButtons.style.display = 'none';
                    profileMessage.innerHTML = '';
                    profileForm.reset();
                });
            }

            // Función para actualizar visualmente los documentos
            function updateDocumentDisplay(docType, documentInfo) {
            // Buscar TODOS los contenedores de documentos
            const allContainers = document.querySelectorAll('.document-field-container');
            let docFieldContainer = null;

            // Buscar el contenedor que tenga un input con el nombre que coincide con docType
            for (const container of allContainers) {
                const input = container.querySelector(`input[name="${docType}"]`);
                if (input) {
                    docFieldContainer = container;
                    break;
                }
            }

            // Si no lo encuentra por nombre exacto, intentar buscarlo por el tipo de documento en la respuesta
            if (!docFieldContainer && documentInfo.document_type) {
                for (const container of allContainers) {
                    const input = container.querySelector(`input[name="${documentInfo.document_type}"]`);
                    if (input) {
                        docFieldContainer = container;
                        break;
                    }
                }
            }

            if (docFieldContainer && documentInfo) {
                console.log('Actualizando documento:', docType, documentInfo);

                // Buscar y eliminar cualquier contenedor de acciones existente
                const existingActions = docFieldContainer.querySelector('.document-actions-container') ||
                                       docFieldContainer.querySelector('.d-flex.align-items-center.gap-2');

                if (existingActions) {
                    console.log('Eliminando acciones existentes');
                    existingActions.remove();
                }

                // Actualizar el badge
                const badge = docFieldContainer.querySelector('.badge');
                if (badge) {
                    badge.innerHTML = '<i class="fa fa-check me-1"></i>Subido';
                    badge.className = 'badge bg-success ms-2';
                } else {
                    // Si no hay badge, crear uno
                    const label = docFieldContainer.querySelector('.col-form-label.fw-bold');
                    if (label) {
                        const newBadge = document.createElement('span');
                        newBadge.className = 'badge bg-success ms-2';
                        newBadge.innerHTML = '<i class="fa fa-check me-1"></i>Subido';
                        label.appendChild(newBadge);
                    }
                }

                // Crear nuevo contenedor de acciones CON ESTILOS DE TRUNCADO
                const docActions = document.createElement('div');
                docActions.className = 'd-flex align-items-center mt-3 gap-2 document-actions-container';

                // Calcular nombre truncado (máximo 25 caracteres)
                const fileName = documentInfo.name || '';
                const truncatedName = fileName.length > 25 ? fileName.substring(0, 25) + '...' : fileName;

                // HTML con estilos de truncado
                docActions.innerHTML = `
                    <span class="badge bg-light text-dark document-name-truncated"
                          title="${fileName.replace(/"/g, '&quot;')}"
                          style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                        ${truncatedName}
                        <small class="text-muted ms-1">
                            (${Math.floor(documentInfo.file_size / 1024)} KB)
                        </small>
                    </span>

                    <!-- Botón Descargar -->
                    <a href="/my/profile/download_document/${documentInfo.id}"
                       class="btn btn-sm btn-outline-primary"
                       target="_blank"
                       title="Descargar documento">
                        <i class="fa fa-download"></i>
                    </a>

                    <!-- Botón Eliminar -->
                    <a href="/my/profile/delete_document/${documentInfo.id}"
                       class="btn btn-sm btn-outline-danger"
                       title="Eliminar documento">
                        <i class="fa fa-trash"></i>
                    </a>
                `;

                // Actualizar información adicional
                const additionalInfo = docFieldContainer.querySelector('.form-text.text-muted');
                if (additionalInfo) {
                    const dateInfo = documentInfo.create_date ?
                        `<br/><i class="fa fa-calendar me-1"></i>Subido el: ${documentInfo.create_date}` : '';
                    additionalInfo.innerHTML = `Formatos aceptados: PDF, JPG, JPEG, PNG, GIF, BMP, TIFF (Máx. 10MB)${dateInfo}`;
                }

                // Resetear el campo de archivo
                const fileInput = docFieldContainer.querySelector('input[type="file"]');
                if (fileInput) {
                    fileInput.value = '';
                }

                // Encontrar el contenedor para insertar las acciones
                const inputContainer = docFieldContainer.querySelector('.flex-grow-1');
                if (inputContainer && inputContainer.parentNode) {
                    inputContainer.parentNode.after(docActions);
                } else {
                    // Si no encuentra el contenedor específico, buscar un lugar apropiado
                    const fileInput = docFieldContainer.querySelector('input[type="file"]');
                    if (fileInput && fileInput.parentNode) {
                        fileInput.parentNode.after(docActions);
                    } else {
                        // Último recurso: agregar al final del contenedor
                        docFieldContainer.appendChild(docActions);
                    }
                }

                console.log('Documento actualizado exitosamente con truncado');

            } else {
                console.error('No se pudo encontrar el contenedor para:', docType, documentInfo);
            }
        }

            // Función para agregar otros documentos
            function addOtherDocument(documentInfo) {
            const otherDocsContainer = document.querySelector('.row:has(.col-md-6.mb-2)');

            if (otherDocsContainer && documentInfo) {
                // Primero, verificar si ya existe un documento con el mismo ID
                const existingDoc = otherDocsContainer.querySelector(`a[href*="/my/profile/download_document/${documentInfo.id}"]`);
                if (existingDoc) {
                    // Si ya existe, actualizar la información
                    const container = existingDoc.closest('.col-md-6.mb-2');
                    if (container) {
                        updateExistingOtherDocument(container, documentInfo);
                    }
                    return;
                }

                // Si no existe, crear uno nuevo
                const colDiv = document.createElement('div');
                colDiv.className = 'col-md-5 mb-2';

                // Calcular nombre truncado
                const fileName = documentInfo.name || '';
                const truncatedName = fileName.length > 20 ? fileName.substring(0, 20) + '...' : fileName;

                const isPdf = fileName.toLowerCase().includes('.pdf');
                const iconClass = isPdf ? 'fa-file-pdf text-danger' : 'fa-file-image text-success';

                colDiv.innerHTML = `
                    <div class="d-flex align-items-center justify-content-between p-2 border rounded">
                        <div class="d-flex align-items-center">
                            <i class="fa ${iconClass} me-2"></i>
                            <div class="other-document-name" title="${fileName.replace(/"/g, '&quot;')}" style="min-width: 0;">
                                <div class="fw-bold text-ellipsis" style="max-width: 150px;">
                                    ${truncatedName}
                                </div>
                                <small class="text-muted">
                                    ${Math.floor(documentInfo.file_size / 1024)} KB
                                    ${documentInfo.create_date ? '- ' + documentInfo.create_date.split(' ')[0] : ''}
                                </small>
                            </div>
                        </div>
                        <div class="d-flex gap-1">
                            <a href="/my/profile/download_document/${documentInfo.id}"
                               class="btn btn-sm btn-outline-primary"
                               target="_blank"
                               title="Descargar">
                                <i class="fa fa-download"></i>
                            </a>
                            <a href="/my/profile/delete_document/${documentInfo.id}"
                               class="btn btn-sm btn-outline-danger delete-other-document"
                               title="Eliminar">
                                <i class="fa fa-trash"></i>
                            </a>
                        </div>
                    </div>
                `;

                otherDocsContainer.appendChild(colDiv);
            }
        }

        // Función para actualizar documentos "otros" existentes
        function updateExistingOtherDocument(container, documentInfo) {
        // Calcular nombre truncado
        const fileName = documentInfo.name || '';
        const truncatedName = fileName.length > 20 ? fileName.substring(0, 20) + '...' : fileName;

        const isPdf = fileName.toLowerCase().includes('.pdf');
        const iconClass = isPdf ? 'fa-file-pdf text-danger' : 'fa-file-image text-success';

        container.innerHTML = `
            <div class="d-flex align-items-center justify-content-between p-2 border rounded">
                <div class="d-flex align-items-center">
                    <i class="fa ${iconClass} me-2"></i>
                    <div class="other-document-name" title="${fileName.replace(/"/g, '&quot;')}" style="min-width: 0;">
                        <div class="fw-bold text-ellipsis" style="max-width: 150px;">
                            ${truncatedName}
                        </div>
                        <small class="text-muted">
                            ${Math.floor(documentInfo.file_size / 1024)} KB
                            ${documentInfo.create_date ? '- ' + documentInfo.create_date.split(' ')[0] : ''}
                        </small>
                    </div>
                </div>
                <div class="d-flex gap-1">
                    <a href="/my/profile/download_document/${documentInfo.id}"
                       class="btn btn-sm btn-outline-primary"
                       target="_blank"
                       title="Descargar">
                        <i class="fa fa-download"></i>
                    </a>
                    <a href="/my/profile/delete_document/${documentInfo.id}"
                       class="btn btn-sm btn-outline-danger delete-other-document"
                       title="Eliminar">
                        <i class="fa fa-trash"></i>
                    </a>
                </div>
            </div>
        `;
    }

    // Función para inicializar tooltips en elementos recién creados
function initDocumentTooltips() {
    // Seleccionar todos los elementos con nombres truncados
    const truncatedElements = document.querySelectorAll('.document-name-truncated, .text-ellipsis');

    truncatedElements.forEach(element => {
        // Si el título es diferente del contenido visible, agregar comportamiento de tooltip
        const fullName = element.title || element.getAttribute('data-fullname');
        const visibleText = element.textContent || element.innerText;

        if (fullName && fullName.length > 25 && !element.hasAttribute('data-tooltip-initialized')) {
            element.setAttribute('data-tooltip-initialized', 'true');

            // Agregar event listener para tooltip
            element.addEventListener('mouseenter', function(e) {
                // Crear tooltip si no existe
                let tooltip = element.querySelector('.custom-tooltip');
                if (!tooltip && this.title) {
                    tooltip = document.createElement('div');
                    tooltip.className = 'custom-tooltip';
                    tooltip.textContent = this.title;
                    tooltip.style.cssText = `
                        position: absolute;
                        bottom: 100%;
                        left: 50%;
                        transform: translateX(-50%);
                        background: #333;
                        color: white;
                        padding: 5px 10px;
                        border-radius: 4px;
                        font-size: 12px;
                        white-space: nowrap;
                        z-index: 1000;
                        margin-bottom: 5px;
                        box-shadow: 0 2px 5px rgba(0,0,0,0.2);
                    `;
                    this.style.position = 'relative';
                    this.appendChild(tooltip);
                }
            });

            element.addEventListener('mouseleave', function() {
                const tooltip = this.querySelector('.custom-tooltip');
                if (tooltip) {
                    tooltip.remove();
                }
            });
        }
    });
}

            // Envío del formulario con AJAX
            if (profileForm) {
                profileForm.addEventListener('submit', async function (e) {
                    e.preventDefault();
                    const formData = new FormData(profileForm);

                    try {
                        const response = await fetch('/my/profile', {
                            method: 'POST',
                            body: formData,
                            headers: {
                                'Accept': 'application/json',
                            },
                        });

                        if (!response.ok) {
                            throw new Error(`HTTP error! status: ${response.status}`);
                        }

                        const result = await response.json();

                        profileMessage.innerHTML = '';
                        if (result.success) {
                            profileMessage.innerHTML = '<div class="alert alert-success" role="alert">Profile successfully updated.</div>';
                            inputs.forEach(input => {
                                input.setAttribute('disabled', 'disabled');
                            });
                            editButton.style.display = 'block';
                            actionButtons.style.display = 'none';

                            // Actualizar dinámicamente el nombre y el email en el DOM
                            if (result.updated_values) {
                                if (result.updated_values.name) {
                                    setProfileHeader({ name: result.updated_values.name });
                                }
                                if (result.updated_values.email) {
                                    setProfileHeader({ email: result.updated_values.email });
                                }
                            }

                            if (result.updated_values && result.updated_values.image_1920) {
                                let imgEl = document.querySelector('img.profile-photo');
                                const container = document.querySelector('.my-profile-container-1');
                                if (!imgEl) {
                                    imgEl = document.createElement('img');
                                    imgEl.className = 'profile-photo';
                                    container.insertBefore(imgEl, container.firstChild);
                                    const svgPlaceholder = container.querySelector('svg.profile-photo');
                                    if (svgPlaceholder) {
                                        svgPlaceholder.style.display = 'none';
                                    }
                                }
                                imgEl.src = 'data:image/png;base64,' + result.updated_values.image_1920;
                            }

                            // Actualizar documentos subidos dinámicamente
                            if (result.uploaded_documents) {
                                Object.entries(result.uploaded_documents).forEach(([docType, docInfo]) => {
                                    updateDocumentDisplay(docType, docInfo);
                                });
                            }

                            // Agregar otros documentos dinámicamente
                            if (result.other_documents && result.other_documents.length > 0) {
                                result.other_documents.forEach(docInfo => {
                                    addOtherDocument(docInfo);
                                });
                            }

                            // Limpiar el campo de otros documentos si se subió algo
                            if (result.other_documents && result.other_documents.length > 0) {
                                const otrosDocumentosInput = document.getElementById('otros_documentos');
                                if (otrosDocumentosInput) {
                                    otrosDocumentosInput.value = '';
                                }
                            }

                        } else {
                            const errors = result.error_message || ['An error occurred. Please try again.'];
                            profileMessage.innerHTML = errors.map(err => `<div class="alert alert-danger" role="alert">${err}</div>`).join('');
                        }
                    } catch (error) {
                        console.error('Error en la solicitud:', error);
                        profileMessage.innerHTML = `<div class="alert alert-danger" role="alert">Error: ${error.message}. Please try again.</div>`;
                    }
                });
            }
        });


document.addEventListener('DOMContentLoaded', function () {
    // Selecciona directamente el contenedor header responsive
    const responsiveHeader = document.querySelector('.responsive-header');
    const confAccount = document.querySelector('.conf-account');
    const currentSectionText = document.getElementById('current-section');
    const currentIconDiv = document.getElementById('current-icon');

    // Al hacer clic en el responsiveHeader, se muestra/oculta el menú
    if (responsiveHeader && confAccount) {
        responsiveHeader.addEventListener('click', function () {
            confAccount.classList.toggle('active');
        });
    }

    // Actualiza el encabezado responsive cuando se hace clic en un item del menú
    const menuItems = document.querySelectorAll('.menu-item');
    menuItems.forEach(item => {
        item.addEventListener('click', function (e) {
        // Verificar si es un enlace externo (con target="_blank")
            const link = this.querySelector('a');
            if (link && link.hasAttribute('target') && link.getAttribute('target') === '_blank') {
                // No hacer nada, dejar que el enlace funcione normalmente
                return;
            }
            e.preventDefault();
            // Extrae el texto y el SVG de la opción activa
            const text = this.querySelector('p')?.innerText || 'Sección';
            currentSectionText.textContent = text;
            const svgElement = this.querySelector('svg');
            if(svgElement && currentIconDiv){
                const iconClone = svgElement.cloneNode(true);
                currentIconDiv.innerHTML = "";
                currentIconDiv.appendChild(iconClone);
            }
            // Cierra el menú en mobile
            confAccount.classList.remove('active');
        });
    });

    // Opcional: Inicializa el encabezado con el item que tenga clase 'active'
    const activeItem = document.querySelector('.menu-item.active');
    if (activeItem) {
        const initialText = activeItem.querySelector('p')?.innerText || 'Sección';
        currentSectionText.textContent = initialText;
        const initialSvg = activeItem.querySelector('svg');
        if (initialSvg && currentIconDiv) {
            const svgClone = initialSvg.cloneNode(true);
            currentIconDiv.innerHTML = "";
            currentIconDiv.appendChild(svgClone);
        }
    }
});


    document.addEventListener('DOMContentLoaded', function() {
    // Función para eliminar documentos mediante AJAX
    function handleDeleteDocument(e) {
        // Prevenir el comportamiento predeterminado solo si es un enlace de eliminación
        if (this.getAttribute('href') && this.getAttribute('href').includes('delete_document')) {
            e.preventDefault();

            const deleteUrl = this.getAttribute('href');
            const deleteButton = this;
            const container = this.closest('.document-field-container') || this.closest('.col-md-6.mb-2');

            // Mostrar confirmación una sola vez
            if (!confirm('¿Estás seguro de que quieres eliminar este documento?')) {
                return;
            }

            // Guardar referencias para restablecer la UI
            const isMainDocument = this.closest('.document-field-container') !== null;
            const isOtherDocument = this.closest('.col-md-6.mb-2') !== null;

            // Mostrar indicador de carga
            const originalContent = deleteButton.innerHTML;
            deleteButton.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';
            deleteButton.disabled = true;

            // Realizar la solicitud AJAX
            fetch(deleteUrl, {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest'
                }
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    // Mostrar mensaje de éxito
                    showAlert('success', data.message);

                    // Actualizar la interfaz según el tipo de documento
                    if (isMainDocument && container) {
                        // Para documentos principales
                        updateMainDocumentUI(container);
                    } else if (isOtherDocument && container) {
                        // Para documentos adicionales - eliminar la fila completa
                        container.remove();
                    }
                } else {
                    showAlert('danger', data.message || 'Error al eliminar el documento');
                    // Restaurar botón
                    deleteButton.innerHTML = originalContent;
                    deleteButton.disabled = false;
                }
            })
            .catch(error => {
                console.error('Error:', error);
                showAlert('danger', 'Error en la solicitud');
                deleteButton.innerHTML = originalContent;
                deleteButton.disabled = false;
            });
        }
    }

    // Función para actualizar la UI de documentos principales
    function updateMainDocumentUI(container) {
    // Encontrar y eliminar el contenedor de acciones del documento
    const actionsDiv = container.querySelector('.document-actions-container') ||
                       container.querySelector('.d-flex.align-items-center.gap-2');

    if (actionsDiv) {
        actionsDiv.remove();
    }

    // Actualizar el badge a estado "pendiente"
    const badge = container.querySelector('.badge.bg-success');
    if (badge) {
        badge.innerHTML = '<i class="fa fa-exclamation-triangle me-1"></i>Pendiente';
        badge.className = 'badge bg-warning text-dark ms-2';
    } else {
        // Si no hay badge, crear uno
        const label = container.querySelector('.col-form-label.fw-bold');
        if (label) {
            const newBadge = document.createElement('span');
            newBadge.className = 'badge bg-warning text-dark ms-2';
            newBadge.innerHTML = '<i class="fa fa-exclamation-triangle me-1"></i>Pendiente';
            label.appendChild(newBadge);
        }
    }

    // Resetear el campo de archivo
    const fileInput = container.querySelector('input[type="file"]');
    if (fileInput) {
        fileInput.value = '';
    }

    // Actualizar la información de fecha
    const smallText = container.querySelector('.form-text.text-muted');
    if (smallText) {
        // Buscar la línea con la fecha y eliminarla
        const lines = smallText.innerHTML.split('<br/>');
        const filteredLines = lines.filter(line => !line.includes('Subido el:'));
        smallText.innerHTML = filteredLines.join('<br/>');
    }
}

    // Función para mostrar alertas
    function showAlert(type, message) {
        // Buscar contenedor de mensajes
        let alertContainer = document.querySelector('#profile-message');
        if (!alertContainer) {
            // Crear contenedor si no existe
            alertContainer = document.createElement('div');
            alertContainer.id = 'profile-message';
            const form = document.querySelector('#profile-form');
            if (form) {
                form.insertBefore(alertContainer, form.firstChild);
            }
        }

        // Crear alerta
        const alertDiv = document.createElement('div');
        alertDiv.className = `alert alert-${type} alert-dismissible fade show`;
        alertDiv.role = 'alert';
        alertDiv.innerHTML = `
            <i class="fa ${type === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle'} me-2"></i>
            ${message}
            <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
        `;

        // Limpiar alertas anteriores y agregar nueva
        alertContainer.innerHTML = '';
        alertContainer.appendChild(alertDiv);

        // Auto-eliminar después de 5 segundos
        setTimeout(() => {
            if (alertDiv.parentNode === alertContainer) {
                alertDiv.remove();
            }
        }, 5000);
    }

    // SOLUCIÓN: Usar UN solo mecanismo de event listeners
    // Opción 1: Delegación de eventos (recomendado)
    document.addEventListener('click', function(e) {
        // Verificar si se hizo clic en un enlace de eliminar
        const deleteLink = e.target.closest('a[href*="delete_document"]');
        if (deleteLink) {
            e.preventDefault();
            handleDeleteDocument.call(deleteLink, e);
        }
    });

    // Validación de archivos en el cliente
    document.querySelectorAll('input[type="file"]').forEach(input => {
        input.addEventListener('change', function() {
            if (this.files.length > 0) {
                const file = this.files[0];
                const maxSize = 10 * 1024 * 1024; // 10MB

                // Validar tamaño
                if (file.size > maxSize) {
                    showAlert('warning', 'El archivo excede el tamaño máximo de 10MB');
                    this.value = '';
                    return;
                }

                // Validar extensión
                const fileName = file.name.toLowerCase();
                const validExtensions = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff'];
                const hasValidExtension = validExtensions.some(ext => fileName.endsWith(ext));

                if (!hasValidExtension) {
                    showAlert('warning', 'Formato de archivo no válido. Solo se permiten PDF e imágenes.');
                    this.value = '';
                    return;
                }
            }
        });
    });
});
